//! The runtime library for Rust code generated by tsurara (design.md 18.9, docs/languages/rust.md).
//!
//! Generated functions pass an OperationDef to [`Client::request`], which builds the request, sends
//! it through a [`Transport`] (reqwest by default), and returns `Result<Success<S>, Failure<E>>`.
//! It re-exports `serde` and `serde_json`, so generated code needs no other dependency.

// `Failure` is matched by callers (`Failure::Http { status, body, .. }`), so its variants are not
// boxed even though they make the `Err` side of results large.
#![allow(clippy::result_large_err)]

mod file;
mod macros;
mod nullable;

pub use file::File;
pub use nullable::Nullable;
pub use serde;
pub use serde_json;

// The client: everything that sends requests (feature `client`, on by default). Generated types need
// only the items above, so `default-features = false` gives them without tokio or an HTTP library.
#[cfg(feature = "client")]
mod client;
#[cfg(feature = "client")]
pub use client::*;
#[cfg(feature = "client")]
pub mod def;
#[cfg(feature = "client")]
mod encode;
#[cfg(feature = "client")]
mod retry;
#[cfg(feature = "client")]
mod sequences;
#[cfg(feature = "client")]
pub mod serialize;
#[cfg(feature = "client")]
pub use def::{OPERATION_DEF_VERSION, OperationDef, OperationInfo, SecurityUse};
#[cfg(feature = "client")]
pub use retry::{Retry, retry_after};
#[cfg(feature = "client")]
pub use sequences::{ItemError, Items};

#[cfg(all(feature = "client", feature = "testing"))]
pub mod testing;
